const fs=require('fs');const puppeteer=require('puppeteer-core');const BASE='https://dev.elmercadodeorigen.com';const sleep=ms=>new Promise(r=>setTimeout(r,ms));const R={errors:[],warnings:[],checks:{},runtime:{}};
function ign(req){const u=req.url(),e=req.failure()?.errorText||'';if(/google-analytics|googletagmanager|doubleclick|clarity|facebook|notification\.mp3|fonts\.googleapis|fonts\.gstatic/i.test(u))return true;if(/ERR_ABORTED/i.test(e)&&(/wp-admin\/admin-ajax\.php|wc-ajax=/i.test(u)||req.resourceType()==='document'))return true;return false}function attach(page,key){const ce=[],rf=[];page.on('console',m=>{if(m.type()==='error'&&!/favicon|third-party cookie|permissions policy/i.test(m.text()))ce.push(m.text())});page.on('requestfailed',q=>{if(!ign(q))rf.push(`${q.url()} :: ${q.failure()?.errorText||'failed'}`)});R.runtime[key]={ce,rf}}
async function visible(el,screen=false){if(!el)return false;return el.evaluate((n,screen)=>{const r=n.getBoundingClientRect(),s=getComputedStyle(n),v=r.width>0&&r.height>0&&s.display!=='none'&&s.visibility!=='hidden'&&+s.opacity>0;return v&&(!screen||(r.right>0&&r.bottom>0&&r.left<innerWidth&&r.top<innerHeight))},screen).catch(()=>false)}async function first(page,sel,screen=false){for(const e of await page.$$(sel))if(await visible(e,screen))return e;return null}async function click(page,e){if(!e)return false;await e.evaluate(n=>n.scrollIntoView({block:'center',inline:'nearest'})).catch(()=>{});await sleep(120);try{await e.click({delay:20})}catch{await e.evaluate(n=>n.click())}return true}
async function go(page,path,label){const raw=path.startsWith('http')?path:BASE+path,url=raw+(raw.includes('?')?'&':'?')+'qa='+Date.now();const res=await page.goto(url,{waitUntil:'domcontentloaded',timeout:60000});await page.addStyleTag({content:'#cookie-law-info-bar,#cookie-law-info-again,#ht-ctc-chat,.grecaptcha-badge{display:none!important}'}).catch(()=>{});await sleep(850);if(!res||res.status()>=400)R.errors.push(`${label}: HTTP ${res?.status()||'none'}`);if(await page.evaluate(()=>document.documentElement.scrollWidth>document.documentElement.clientWidth+3).catch(()=>false))R.errors.push(`${label}: horizontal overflow`);return res}async function shot(page,n){await page.screenshot({path:`qa/${n}.png`,fullPage:true})}async function safe(l,f){try{await f()}catch(e){R.errors.push(`${l}: ${e.message}`)}}
async function badge(page){return page.evaluate(()=>{const q='.site-header .shop-cart-count,.site-header .shopping-cart-count,.site-header .cart-count,.site-header .count,.site-header .mini-cart-count,.site-header .elmercado-cart-direct-count';for(const n of document.querySelectorAll(q)){const r=n.getBoundingClientRect(),s=getComputedStyle(n);if(r.width>0&&r.height>0&&s.display!=='none'&&s.visibility!=='hidden'&&+s.opacity>0){const m=(n.textContent||'').match(/\d+/);return{visible:true,value:m?+m[0]:0}}}return{visible:false,value:0}})}
async function home(page,mode){await go(page,'/',`home ${mode}`);await shot(page,`v9-home-${mode}`);const z=await badge(page);if(z.visible&&z.value<1)R.errors.push(`home ${mode}: zero cart badge visible`);const h=await page.evaluate(()=>{const s=document.querySelector('.site-header-inner>.woostify-container'),b=document.querySelector('.site-branding'),t=document.querySelector('.site-tools');if(!s||!b||!t)return null;const a=s.getBoundingClientRect(),x=b.getBoundingClientRect(),y=t.getBoundingClientRect();return{brand:Math.abs(a.top+a.height/2-x.top-x.height/2),tools:Math.abs(a.top+a.height/2-y.top-y.height/2)}});if(!h)R.errors.push(`home ${mode}: header structure missing`);else if(h.brand>7||h.tools>7)R.errors.push(`home ${mode}: header alignment outside tolerance`);if(mode==='mobile'&&await page.$('.emo-featured-products ul.products')){await page.$eval('.emo-featured-products',e=>e.scrollIntoView({block:'center'}));await sleep(450);const p=await first(page,'.emo-carousel-control--previous',true),n=await first(page,'.emo-carousel-control--next',true);if(!p||!n)R.errors.push('home mobile: carousel arrows missing');if(n){const a=await page.$eval('.emo-featured-products ul.products',e=>e.scrollLeft);await click(page,n);await sleep(550);const b=await page.$eval('.emo-featured-products ul.products',e=>e.scrollLeft);if(b<=a+2)R.errors.push('home mobile: carousel arrow does not move products')}}await page.evaluate(()=>scrollTo(0,0));await page.keyboard.press('Tab');await page.keyboard.press('Tab');if(!(await page.evaluate(()=>document.activeElement&&document.activeElement!==document.body)))R.errors.push(`home ${mode}: keyboard focus not reachable`)}
