async function modeAudit(browser,name,vp,products,simple){const ctx=await browser.createBrowserContext(),p=await ctx.newPage();await p.setViewport(vp);p.setDefaultNavigationTimeout(60000);attach(p,name);await safe(`home ${name}`,()=>home(p,name));if(name==='mobile')await safe('mobile menu',()=>menu(p));await safe(`search ${name}`,()=>search(p,name));await safe(`shop ${name}`,()=>shop(p,name));await safe(`product states ${name}`,()=>productStates(p,name,products));await safe(`commerce ${name}`,()=>commerce(p,name,simple));await safe(`content ${name}`,()=>content(p,name));const x=R.runtime[name],ce=[...new Set(x.ce)],rf=[...new Set(x.rf)];if(ce.length)R.errors.push(`${name}: console errors: ${ce.slice(0,3).join(' | ')}`);if(rf.length)R.errors.push(`${name}: request failures: ${rf.slice(0,3).join(' | ')}`);await ctx.close()}
(async()=>{fs.mkdirSync('qa',{recursive:true});const products=await fetch(`${BASE}/wp-json/wc/store/v1/products?per_page=100`).then(r=>r.json());const simple=products.find(p=>p.is_purchasable&&p.is_in_stock&&p.type==='simple');const b=await puppeteer.launch({executablePath:'/usr/bin/google-chrome',headless:'new',protocolTimeout:120000,args:['--no-sandbox','--disable-dev-shm-usage']});try{const c=await b.createBrowserContext(),p=await c.newPage();await p.setViewport({width:1440,height:1000});attach(p,'clean');await go(p,'/carrito/','empty cart');if(!await p.evaluate(()=>/carrito.*vac[ií]o|tu carrito est[aá] vac[ií]o|volver a la tienda|return to shop/i.test(document.body.innerText)))R.errors.push('empty cart state missing');const z=await badge(p);if(z.visible&&z.value<1)R.errors.push('empty cart: zero badge visible');await go(p,'/mi-cuenta/','account logged out');if(!await p.$('form.woocommerce-form-login,input[name="username"],input[name="password"]'))R.errors.push('account logged-out form missing');const x=R.runtime.clean;if([...new Set(x.ce)].length)R.errors.push('clean: console errors');if([...new Set(x.rf)].length)R.errors.push('clean: request failures');await c.close();await modeAudit(b,'desktop',{width:1440,height:1000},products,simple);await modeAudit(b,'mobile',{width:390,height:844,isMobile:true,hasTouch:true,deviceScaleFactor:1},products,simple)}finally{await b.close()}R.errors=[...new Set(R.errors)];R.warnings=[...new Set(R.warnings)];fs.writeFileSync('qa/report-v9.json',JSON.stringify(R,null,2));if(R.errors.length){console.error(R.errors.join('\n'));process.exitCode=2}else console.log(`AUDIT_OK warnings=${R.warnings.length}`)})();